### Arithmetic Expressions with Parsing Expression Grammar

Consider the following PEG for arithmetic expressions:

    S ← E
    E ← T ('+' T)*
    T ← F ('×' F)*
    F ← P'²' / P
    P ← 'a' / '(' E ')'

Implement it as a backtracking parser, following the rules from the course notes. You may use the commented version of method `literal`.

```python
class Backtrack:
  src: str

  def literal(self, k: int, a: str):
    if self.src.startswith(a, k):
      return k + len(a)
    # if self.src.startswith(a, k): print('match', a, 'at', k); return k + len(a)
    # else: print('fail', a, 'at', k); return None

  def S(self, k):
    return self.E(k)

  def E(self, k):
    k = self.T(k)
    if k is None:
      return None
    while True:
      k2 = self.literal(k, '+')
      if k2 is None:
        break
      k2 = self.T(k2)
      if k2 is None:
        break
      k = k2
    return k

  def T(self, k):
    k = self.F(k)
    if k is None:
      return None
    while True:
      k2 = self.literal(k, '×')
      if k2 is None:
        break
      k2 = self.F(k2)
      if k2 is None:
        break
      k = k2
    return k

  def F(self, k):
    k2 = self.P(k)
    if k2 is not None:
      k3 = self.literal(k2, '²')
      if k3 is not None:
        return k3
    return self.P(k)

  def P(self, k):
    k2 = self.literal(k, 'a')
    if k2 is not None:
      return k2
    k2 = self.literal(k, '(')
    if k2 is None:
      return None
    k2 = self.E(k2)
    if k2 is None:
      return None
    return self.literal(k2, ')')

  def parse(self, s: str):
    self.src = s
    return self.S(0) == len(s)
```
